#include "geometry.hpp"
#include <random>
#include <numeric>
#include <functional>
using U=uint64_t;
struct Effect{U one=0,two=0,three=0;};
struct Node{U pose=0,m=0;int made=0,parent=-1,score=0;vector<int> seq;};
struct Back{U pose=0,ones=0,zeros=0;vector<int> tail;int score=0;};
struct Hist{int parent;vector<int> seq;};
U T,F;int C,seed0;vector<pair<U,vector<int>>> discoveries;unordered_set<U> discoveredPoses;int goalDistances[8][6][256];U rootPose,goalPose;long long visitedN=0,bridgeN=0;mt19937 gen;
array<array<array<int,4>,256>,6> moveByte;
U rayByte[6][256];
vector<Hist> hist;vector<int> answer;U answerPose=0;int answerCopies=0;
U transformPose(U q,int mask){U z=q;for(int e=0;e<3;e++)if(mask>>e&1){int a=(q>>(8*e))&255,b=(q>>(8*(e+3)))&255;int pa=((3-2*e)*R-(b&127)+2*L)%L,pb=((3-2*e)*R-(a&127)+2*L)%L;z&=~((255ULL<<(8*e))|(255ULL<<(8*(e+3))));z|=U(pa+(b&128))<<(8*e);z|=U(pb+(a&128))<<(8*(e+3));}return z;}
U canonical(U q){U z=q;for(int mask=1;mask<8;mask++)z=min(z,transformPose(q,mask));return z;}
int pdist(U a,U b){int best=1000;for(int mask=0;mask<8;mask++){U q=transformPose(b,mask);int d=0;for(int e=0;e<6;e++){int p=(a>>(8*e))&127,v=(q>>(8*e))&127;d=max(d,min((p-v+L)%L,(v-p+L)%L)+int(((a^q)>>(8*e+7))&1));}best=min(best,d);}return best;}
Effect effect(U pose){Effect v;for(int e=0;e<6;e++){U ray=rayByte[e][(pose>>(8*e))&255];v.three|=v.two&ray;v.two|=v.one&ray;v.one|=ray;}return v;}
Node step(Node s,int action){U p=0;for(int e=0;e<6;e++)p|=U(moveByte[e][(s.pose>>(8*e))&255][(action>>(2*e))&3])<<(8*e);s.pose=p;auto v=effect(p);s.m=(s.m|v.two)&~v.three;if((s.m&T)==T&&!(s.m&F)){s.m&=~T;s.made++;}return s;}
vector<int> recover(int parent,const vector<int>&seq){vector<vector<int>> chunks={seq};for(int p=parent;p>=0;p=hist[p].parent)chunks.push_back(hist[p].seq);vector<int> out;for(auto it=chunks.rbegin();it!=chunks.rend();it++)out.insert(out.end(),it->begin(),it->end());return out;}
bool acceptCandidate(const vector<int>&p){Node s;s.pose=rootPose;int t=0;for(int a:p){int old=s.made;s=step(s,a);t++;if(s.made==C&&s.made!=old&&(goalPose==UINT64_MAX||canonical(s.pose)==canonical(goalPose))){if(answer.empty()||t<(int)answer.size()){answer.assign(p.begin(),p.begin()+t);answerPose=s.pose;answerCopies=s.made;}U canon=canonical(s.pose);if(discoveries.size()<24&&discoveredPoses.insert(canon).second)discoveries.push_back({s.pose,vector<int>(p.begin(),p.begin()+t)});return true;}if(s.made>=C)return false;}return false;}
int scoreNode(const Node& s,int variant){int good=pc(s.m&T),bad=pc(s.m&F);auto v=effect(s.pose);int bw=(variant%3==0?130:variant%3==1?210:300);int score=s.made*(NT*180+128)+good*128-bad*bw+pc(v.one&T&~s.m)*10-pc(v.three&T)*4;if(goalPose!=UINT64_MAX){int best=100;for(int mask=0;mask<8;mask++){int d=0;for(int e=0;e<6;e++)d=max(d,goalDistances[mask][e][(s.pose>>(8*e))&255]);best=min(best,d);}score-=best*(s.made+1==C?32:10);}return score;}
struct Trip{U pose=0;int act=0;Effect v;};
array<Trip,64> triples(U pose,int first){array<Trip,64> out{};for(int code=0;code<64;code++){auto &x=out[code];for(int j=0;j<3;j++){int e=first+j,op=(code>>(2*j))&3,b=moveByte[e][(pose>>(8*e))&255][op];x.pose|=U(b)<<(8*e);x.act|=op<<(2*e);U ray=rayByte[e][b];x.v.three|=x.v.two&ray;x.v.two|=x.v.one&ray;x.v.one|=ray;}}return out;}
void keepNode(vector<Node>&pool,Node n,int cap){auto cmp=[](const Node&a,const Node&b){return a.score>b.score;};if((int)pool.size()<cap){pool.push_back(move(n));push_heap(pool.begin(),pool.end(),cmp);}else if(n.score>pool[0].score){pop_heap(pool.begin(),pool.end(),cmp);pool.back()=move(n);push_heap(pool.begin(),pool.end(),cmp);}}
void prune(vector<Node>&pool,int width){sort(pool.begin(),pool.end(),[](auto&a,auto&b){return a.score>b.score;});unordered_set<U> exact,boards;vector<Node> out;for(int pass=0;pass<2&&(int)out.size()<width;pass++)for(auto &n:pool){U hash=mix(canonical(n.pose))^mix(n.m)^mix(n.made+181);if(exact.count(hash))continue;U bh=mix(n.m)^mix(n.made+181);if(pass==0&&boards.count(bh))continue;exact.insert(hash);boards.insert(bh);hist.push_back({n.parent,n.seq});n.parent=int(hist.size())-1;n.seq.clear();out.push_back(n);if((int)out.size()>=width)break;}pool=move(out);}
vector<vector<int>> chordPlans(U pose,int axis,int H){vector<vector<int>> out;int e=axis,j=axis+3;int pe=(pose>>(8*e))&255,pj=(pose>>(8*j))&255;for(int p=0;p<L;p++){int q=((3-2*e)*R-p+2*L)%L;if(!rays[p][e].b[0])continue;int d0=(p-(pe&127)+L+L/2)%L-L/2,d1=(q-(pj&127)+L+L/2)%L-L/2;if(abs(d0)+!(pe&128)>H||abs(d1)+!(pj&128)>H)continue;for(int timing=0;timing<2;timing++){vector<int> plan(H);for(auto z:vector<tuple<int,int,int>>{{e,pe,d0},{j,pj,d1}}){auto[i,b,d]=z;int t=0;if(!(b&128)&&timing==1){plan[t++]|=3<<(2*i);}for(int v=0;v<abs(d);v++)plan[t++]|=(d>0?2:1)<<(2*i);if(!(b&128)&&timing==0)plan[t++]|=3<<(2*i);}out.push_back(plan);}}return out;}
void macroExpand(const Node&parent,int t,int H,vector<vector<Node>>&layers,int variant,int cap){for(int axis=0;axis<3;axis++){auto plans=chordPlans(parent.pose,axis,H);int clip[4],nclip=0;for(int e=0;e<6;e++)if(e!=axis&&e!=axis+3)clip[nclip++]=e;for(auto &pairplan:plans)for(int code=0;code<256;code++){
 if((visitedN++&2047)==0&&Clock::now()>=deadline)return;Node s=parent;vector<int> seq;for(int h=0;h<H;h++){int act=pairplan[h];for(int j=0;j<4;j++){int op=(code>>(2*j))&3;if(op==3&&h>0)op=0;act|=op<<(2*clip[j]);}int old=s.made;s=step(s,act);seq.push_back(act);if(s.made>=C){if(s.made==C&&s.made!=old&&(goalPose==UINT64_MAX||canonical(s.pose)==canonical(goalPose)))acceptCandidate(recover(parent.parent,seq));break;}if(h+1==H){s.seq=seq;s.parent=parent.parent;s.score=scoreNode(s,variant);keepNode(layers[t+H],move(s),cap);}}}}}
void forwardBeam(int horizon,int variant,bool macros){hist.clear();vector<vector<Node>> layers(horizon+1);Node root;root.pose=rootPose;layers[0].push_back(root);int cap=WIDTH*8;
 for(int t=0;t<horizon&&Clock::now()<deadline;t++){/* Retain alternative acceptance poses. */auto &beam=layers[t];if(beam.empty())continue;prune(beam,WIDTH);for(auto &parent:beam){if(macros){for(int h=2;h<=3;h++)if(t+h<=horizon)macroExpand(parent,t,h,layers,variant,cap);}auto aa=triples(parent.pose,0),bb=triples(parent.pose,3);
 for(auto&a:aa)for(auto&b:bb){if((visitedN++&8191)==0&&Clock::now()>=deadline)return;U two=a.v.two|b.v.two|(a.v.one&b.v.one),three=a.v.three|b.v.three|(a.v.two&b.v.one)|(a.v.one&b.v.two);Node s;s.pose=a.pose|b.pose;s.m=(parent.m|two)&~three;s.made=parent.made;s.parent=parent.parent;s.seq={a.act|b.act};if((s.m&T)==T&&!(s.m&F)){s.m&=~T;s.made++;}if(s.made>=C){if(s.made==C&&(goalPose==UINT64_MAX||canonical(s.pose)==canonical(goalPose)))acceptCandidate(recover(s.parent,s.seq));continue;}s.score=scoreNode(s,variant);keepNode(layers[t+1],move(s),cap);}
 }} }
vector<vector<int>> pathsTo(int start,int end,int D){vector<vector<int>> out;vector<int> path;function<void(int,int)> dfs=[&](int b,int t){int p=b&127,q=end&127,dist=min((p-q+L)%L,(q-p+L)%L)+int((b&128)!=(end&128));if(dist>D-t)return;if(t==D){if(b==end)out.push_back(path);return;}for(int op=0;op<4;op++){path.push_back(op);int np=p,a=b&128;if(op==1)np=(p+L-1)%L;else if(op==2)np=(p+1)%L;else if(op==3)a^=128;dfs(np+a,t+1);path.pop_back();}};dfs(start,0);return out;}
bool bridge(const Back& b,int D){vector<vector<int>> options[6];uint64_t count=1;for(int e=0;e<6;e++){options[e]=pathsTo((rootPose>>(8*e))&255,(b.pose>>(8*e))&255,D);if(options[e].empty())return false;count*=options[e].size();if(count>150000)return false;}vector<int> actions(D);bool found=false;function<void(int)> dfs=[&](int e){if(found||Clock::now()>=deadline)return;if(e==6){bridgeN++;Node s;s.pose=rootPose;for(int a:actions)s=step(s,a);if(s.made||((b.ones&~s.m)|(b.zeros&s.m)))return;vector<int> p=actions;p.insert(p.end(),b.tail.begin(),b.tail.end());if(acceptCandidate(p))found=true;return;}for(auto &path:options[e]){for(int t=0;t<D;t++)actions[t]=(actions[t]&~(3<<(2*e)))|(path[t]<<(2*e));dfs(e+1);if(found)return;}};dfs(0);return found;}
vector<U> geometricEnds(const vector<U>&refs){vector<pair<int,U>> pool;unordered_set<U> used;
 for(int axis=0;axis<3;axis++)for(int p=0;p<L;p++){
  U chord=rays[p][axis].b[0];if(!(chord&T))continue;int q=((3-2*axis)*R-p+2*L)%L;int clip[4],nc=0;for(int e=0;e<6;e++)if(e!=axis&&e!=axis+3)clip[nc++]=e;
  vector<int> opts[4];for(int j=0;j<4;j++){int e=clip[j];opts[j].push_back((refs.empty()?0:(refs[0]>>(8*e))&127));for(int v=0;v<L;v++)if(rays[v][e].b[0]&&!(rays[v][e].b[0]&chord&T))opts[j].push_back(v+128);}
  U base=(U(p+128)<<(8*axis))|(U(q+128)<<(8*(axis+3)));
  for(int a:opts[0])for(int b:opts[1])for(int c:opts[2])for(int d:opts[3]){U pose=base|(U(a)<<(8*clip[0]))|(U(b)<<(8*clip[1]))|(U(c)<<(8*clip[2]))|(U(d)<<(8*clip[3]));Effect z=effect(pose);if((z.three&T)|((z.two&~z.three)&F))continue;U can=canonical(pose);if(!used.insert(can).second)continue;int score=pc(z.two&~z.three&T)*128+pc(z.three&F)*24-pdist(pose,rootPose)*12;pool.push_back({score,pose});}
 }
 sort(pool.rbegin(),pool.rend());vector<U> result=refs;for(int i=0;i<min(64,(int)pool.size());i++)result.push_back(pool[i].second);return result;
}
void meetSearch(const vector<U>&inputEnds,int horizon,int variant){auto ends=geometricEnds(inputEnds);vector<Back> beam;for(U end:ends)beam.push_back({end,T,F,{},0});int maxBridge=min(3,horizon);unordered_set<U> seen;
 for(int depth=0;depth<horizon&&Clock::now()<deadline;depth++){vector<Back> pool;int cap=WIDTH*6;for(auto &n:beam){auto eff=effect(n.pose);if((eff.three&n.ones)|((eff.two&~eff.three)&n.zeros))continue;U ones=n.ones&~eff.two,zeros=n.zeros&~eff.three;auto aa=triples(n.pose,0),bb=triples(n.pose,3);for(auto&a:aa)for(auto&b:bb){visitedN++;Back z;z.pose=a.pose|b.pose;z.ones=ones;z.zeros=zeros;int action=a.act|b.act,forward=0;for(int e=0;e<6;e++){int op=(action>>(2*e))&3;if(op==1)op=2;else if(op==2)op=1;forward|=op<<(2*e);}z.tail={forward};z.tail.insert(z.tail.end(),n.tail.begin(),n.tail.end());int distance=0;for(int e=0;e<6;e++){int p=(z.pose>>(8*e))&127,q=(rootPose>>(8*e))&127;distance=max(distance,min((p-q+L)%L,(q-p+L)%L)+int(((z.pose^rootPose)>>(8*e+7))&1));}if(distance+int(z.tail.size())>horizon)continue;U hash=mix(z.pose)^mix(ones)^mix(zeros+531);if(!seen.insert(hash).second)continue;
 z.score=-pc(ones)*200-pc(zeros)*15-distance*(variant%2?45:90);pool.push_back(move(z));if((int)pool.size()>cap*2){nth_element(pool.begin(),pool.begin()+cap,pool.end(),[](auto&a,auto&b){return a.score>b.score;});pool.resize(cap);}if((visitedN&8191)==0&&Clock::now()>=deadline)break;}}
 if(pool.empty())break;sort(pool.begin(),pool.end(),[](auto&a,auto&b){return a.score>b.score;});if((int)pool.size()>WIDTH)pool.resize(WIDTH);beam=move(pool);
 for(auto &n:beam){seen.insert(mix(n.pose)^mix(n.ones)^mix(n.zeros+531));int remain=horizon-int(n.tail.size());for(int d=0;d<=min(maxBridge,remain);d++){if(!answer.empty()&&d+int(n.tail.size())>=(int)answer.size())continue;if(bridge(n,d))break;if(Clock::now()>=deadline)return;}}
 }}
int unused_geometry_main(){ios::sync_with_stdio(false);cin.tie(nullptr);int budget,horizon,mode,width;while(cin>>R>>C>>width>>budget>>horizon>>mode>>seed0){WIDTH=width;vector<string> rows(2*R+1);for(auto&s:rows)cin>>s;cin>>rootPose>>goalPose;int ne;cin>>ne;vector<U> ends(ne);for(auto &p:ends)cin>>p;auto begin=Clock::now();init_geometry(rows,seed0%7);if(W!=1){cout<<"0 0 0 0 0\n"<<flush;continue;}T=target.b[0];F=forbid.b[0];for(int e=0;e<6;e++)for(int a=0;a<2;a++)for(int p=0;p<L;p++){int b=p+128*a;rayByte[e][b]=a?rays[p][e].b[0]:0;moveByte[e][b]={b,(p+L-1)%L+128*a,(p+1)%L+128*a,p+128*(1-a)};}for(int mask=0;mask<8;mask++){U q=transformPose(goalPose==UINT64_MAX?rootPose:goalPose,mask);for(int e=0;e<6;e++)for(int a=0;a<2;a++)for(int p=0;p<L;p++){int v=(q>>(8*e))&255,d=min((p-(v&127)+L)%L,((v&127)-p+L)%L)+int(a!=bool(v&128));goalDistances[mask][e][p+128*a]=d;}}gen.seed(seed0);visitedN=bridgeN=0;discoveries.clear();discoveredPoses.clear();answer.clear();answerPose=0;answerCopies=0;deadline=Clock::now()+chrono::milliseconds(budget);
 if(mode==2)meetSearch(ends,horizon,seed0%7);else forwardBeam(horizon,seed0%7,mode==4);
 auto ms=chrono::duration_cast<chrono::milliseconds>(Clock::now()-begin).count();cout<<answer.size()<<' '<<visitedN<<' '<<ms<<' '<<answerPose<<' '<<bridgeN;for(int a:answer)cout<<' '<<a;cout<<' '<<discoveries.size();for(auto &d:discoveries){cout<<' '<<d.second.size()<<' '<<d.first;for(int a:d.second)cout<<' '<<a;}cout<<'\n'<<flush;
 }}
